// SPDX-License-Identifier: GPL-3.0-only
// AI-assisted example. Edit only the locations object for your sensor names.
const locations = {
    "espth-1": "Living Room",
    "espthsc-1": "Desk Display"
};

const topic = String(msg.topic || "");
const stateMatch = topic.match(/^(.+)\/sensor\/(temperature|humidity|indoor_temperature|indoor_humidity)\/state$/);
const telemetryMatch = topic.match(/^(.+)\/telemetry$/);
if (!stateMatch && !telemetryMatch) return null;

const sensorId = (stateMatch || telemetryMatch)[1];
const number = (value) => {
    if (typeof value !== "number" && typeof value !== "string") return undefined;
    if (typeof value === "string" && !value.trim()) return undefined;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
};
let payload = Buffer.isBuffer(msg.payload) ? msg.payload.toString("utf8") : msg.payload;
let temperatureF;
let humidity;
let sourceTimestamp;

if (stateMatch) {
    const value = number(payload);
    if (stateMatch[2].includes("humidity")) humidity = value;
    else temperatureF = value; // The supplied ESPTH state topic is Fahrenheit.
} else {
    if (typeof payload === "string") {
        try { payload = JSON.parse(payload); } catch { return null; }
    }
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) return null;
    temperatureF = number(payload.temperature_f);
    if (temperatureF === undefined) {
        const temperatureC = number(payload.temperature_c);
        if (temperatureC !== undefined) temperatureF = temperatureC * 9 / 5 + 32;
    }
    humidity = number(payload.humidity_percent);
    sourceTimestamp = payload.timestamp;
}

if (humidity !== undefined && (humidity < 0 || humidity > 100)) humidity = undefined;
if (temperatureF === undefined && humidity === undefined) return null;

const sensors = flow.get("currentSensors") || {};
const current = sensors[sensorId] || {};
if (temperatureF !== undefined) current.temperatureF = temperatureF;
if (humidity !== undefined) current.humidity = humidity;
const candidate = number(sourceTimestamp);
const sampleDate = candidate === undefined ? new Date() : new Date(candidate < 1000000000000 ? candidate * 1000 : candidate);
const recordedAt = Number.isNaN(sampleDate.getTime()) ? new Date() : sampleDate;
const location = locations[sensorId] || `Unassigned (${sensorId})`;
current.sensorId = sensorId;
current.location = location;
current.recordedAt = recordedAt.toISOString();
sensors[sensorId] = current;
flow.set("currentSensors", sensors);

const dbMessage = {
    params: {
        $recorded_at: current.recordedAt,
        $sensor_id: sensorId,
        $location: location,
        $temperature_f: current.temperatureF ?? null,
        $humidity_percent: current.humidity ?? null
    }
};
const currentMessage = { ...current };
const temperatureChart = current.temperatureF === undefined ? null : {
    topic: location,
    action: "append",
    payload: { location, time: recordedAt.getTime(), value: current.temperatureF }
};
const humidityChart = current.humidity === undefined ? null : {
    topic: location,
    action: "append",
    payload: { location, time: recordedAt.getTime(), value: current.humidity }
};
return [dbMessage, currentMessage, temperatureChart, humidityChart];

const temperature = msg.temperatureF === undefined ? "No reading yet" : `${msg.temperatureF.toFixed(1)} deg F`;
const humidity = msg.humidity === undefined ? "No reading yet" : `${msg.humidity.toFixed(1)} %`;
const timestamp = msg.recordedAt ? new Date(msg.recordedAt).toLocaleString() : "No reading yet";
return [
    { payload: `${msg.location} (${msg.sensorId})` },
    { payload: temperature },
    { payload: humidity },
    { payload: timestamp }
];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const toTime = (value) => new Date(value).getTime();
const temperatures = rows.filter(row => Number.isFinite(Number(row.temperature_f))).map(row => ({ location: row.location, time: toTime(row.recorded_at), value: Number(row.temperature_f) }));
const humidity = rows.filter(row => Number.isFinite(Number(row.humidity_percent))).map(row => ({ location: row.location, time: toTime(row.recorded_at), value: Number(row.humidity_percent) }));
return [
    { action: "replace", payload: temperatures },
    { action: "replace", payload: humidity }
];

// Replace all three placeholders before enabling this tab.
const apiKey = "PASTE_YOUR_OPENWEATHER_API_KEY_HERE";
const latitude = "YOUR_LATITUDE";
const longitude = "YOUR_LONGITUDE";
if (apiKey.includes("PASTE_") || latitude.includes("YOUR_") || longitude.includes("YOUR_")) {
    node.warn("OpenWeather is not configured; add an API key and coordinates first.");
    return null;
}
msg.url = `https://api.openweathermap.org/data/2.5/weather?lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}&units=imperial&appid=${encodeURIComponent(apiKey)}`;
return msg;

const weather = msg.payload;
if (!weather || !weather.main || !Number.isFinite(Number(weather.main.temp))) {
    node.warn("OpenWeather returned no usable current temperature.");
    return null;
}
const location = String(weather.name || "OpenWeather location");
const temperatureF = Number(weather.main.temp);
const humidity = Number(weather.main.humidity);
const description = String(weather.weather?.[0]?.description || "No description");
const recordedAt = new Date().toISOString();
return [
    { params: { $recorded_at: recordedAt, $location: location, $temperature_f: temperatureF, $humidity_percent: Number.isFinite(humidity) ? humidity : null, $description: description } },
    { location, temperatureF, description }
];

return [
    { payload: msg.location },
    { payload: `${msg.temperatureF.toFixed(1)} deg F` },
    { payload: msg.description }
];
